"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["22705"],{11793(e){e.exports=JSON.parse('{"id":"FIN-437","slug":"option-premium","term":"Option Premium","also_known_as":[],"difficulty":"Intermediate","definition":"The option premium is the price the buyer of an option pays to the seller for the rights the option provides.","explanation":["The premium is paid upfront when the option is bought. For the buyer, it is the maximum amount they can lose. For the seller, it is the maximum amount they can gain from selling the option, in exchange for taking on the obligation.","Option premiums are usually quoted per unit of the underlying asset. For share options covering 100 shares, a premium of 2.50 means paying 250 for one contract.","The premium has two parts. Intrinsic value is the amount by which the option is already profitable to exercise. Time value is the extra amount reflecting the chance that the option becomes more profitable before expiry.","Several factors affect the premium: the price of the underlying asset compared with the strike price, the time until expiry, the expected volatility of the underlying asset, interest rates and expected dividends. Higher volatility increases premiums, because larger price swings make a big payoff more likely. Longer time to expiry also increases premiums. Option pricing models, such as the Black\u2013Scholes model, combine these factors to estimate a fair premium."],"note":"","total":1500,"prev":{"slug":"option-pool","term":"Option Pool"},"next":{"slug":"ordinary-annuity","term":"Ordinary Annuity"}}')}}]);